from dataclasses import asdict, is_dataclass
from typing import Any, List, Optional

class Order:
    def __init__(self, id: Optional[int], status: str, user_id: Optional[int], items: List[Item]):
        self.id = id
        self.status = status
        self.user_id = user_id
        self.items = items

class Item:
    def __init__(self, price: Optional[float], quantity: Optional[int]):
        self.price = price
        self.quantity = quantity

def validate_order(order: Order) -> Optional[Order]:
    if not is_dataclass(order):
        return None

    if order.status != 'pending':
        return None

    if not order.items or not all(item for item in order.items if isinstance(item, Item)):
        return None

    if not order.user_id:
        return None

    total = sum(item.price * item.quantity for item in order.items)
    return Order(order.id, order.status, order.user_id, order.items)

def process_order(order: Any) -> Any:
    if not is_dataclass(order):
        order = Order(id=order.get('id'), status=order.get('status'), user_id=order.get('user_id'), items=[Item(price=item.get('price'), quantity=item.get('quantity')) for item in (order.get('items') or [])])

    return validate_order(order)
